import{_ as e,o as t,c as o,ag as d}from"./chunks/framework.C5oN-8Wt.js";const u=JSON.parse('{"title":"二值判决","description":"","frontmatter":{},"headers":[],"relativePath":"v0.2.0-alpha/modules/binary_slicer/index.md","filePath":"v0.2.0-alpha/modules/binary_slicer/index.md"}'),r={name:"v0.2.0-alpha/modules/binary_slicer/index.md"};function i(n,a,l,h,c,p){return t(),o("div",null,[...a[0]||(a[0]=[d('<h1 id="二值判决" tabindex="-1">二值判决 <a class="header-anchor" href="#二值判决" aria-label="Permalink to &quot;二值判决&quot;">​</a></h1><p>适用：v0.2.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>binary_slicer</code> · 模块定义版本：1</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>以零为固定阈值，把实数样本判为两个码元索引：负值输出 0，零和正值输出 1。正零与负零都判为 1。</p><p>输出是固定 M=2 的 <code>symbol_u8</code> 码元流，表示编号，不是模拟幅度，也不是任意 byte 数据。它可用于研究实数基带信号的硬判决。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>正交解调.out → 二值判决.in → 符号映射器.in</code>。映射器选择与 M=2 对应的 BPSK 星座，把索引重新变成复数点。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（输入）</td><td><code>numeric_f64</code></td><td>归一化幅度；vlen=1</td></tr><tr><td>输出</td><td><code>out</code>（码元输出）</td><td><code>symbol_u8</code></td><td>索引；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>本模块没有可调参数，阈值固定为零，码元数量固定为 2。输入只接收标量实数流，每个输入 item 对应一个输出码元，采样率不变。</p><p>连接下游时须保持码元域一致：M=2 的映射器可以接收，M=4 的映射器不能直接接收。若研究其他判决边界，应先明确上游信号如何平移或缩放，不能在本模块中填写不存在的阈值字段。</p><p>此模块没有可编辑计算参数。</p><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>计算参数或结构变化后，先停止，再重新准备和运行。</p><p>本模块没有在线参数。改变判决结果需要改变实际输入；更换接线或下游码元域后，停止并重新准备工程。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="调频、幅相、正交解调与二值-bpsk-映射" tabindex="-1">调频、幅相、正交解调与二值 BPSK 映射 <a class="header-anchor" href="#调频、幅相、正交解调与二值-bpsk-映射" aria-label="Permalink to &quot;调频、幅相、正交解调与二值 BPSK 映射&quot;">​</a></h3><p><a href="../../../downloads/v0.2.0-alpha/modulation-chain.cnsproj" download>下载 modulation-chain.cnsproj</a></p><p>在 PC 上打开工程，按 F5 运行。有限运行可将参考源样本数设为 2048 item；重新打开工程后需再次运行以取得数据。</p><p>调频、幅相、正交解调与二值 BPSK 映射</p><ul><li>Fs=4096，常量 1 经 sensitivity=π/8 调频得到 +256 Hz、模长 1 的复相量，首项先累加。幅相输出主值相位；gain=8/π 解调首项为 0、后续约 1。二值判决对零和正值均输出索引 1，按生产 BPSK 点表映射。码元 OUT 固定 M2，不生成模拟幅度频谱。</li></ul><p>调频与判决示例将正交解调器接入本模块，再连接 BPSK 符号映射器。解调器预期首项为 0，后续约为 1；因为零也判为 1，这些样本的判决结果均应为索引 1。采用预设 BPSK 点表时，映射后应落在复数点 <code>+1+j0</code>。</p><p>查看判决结果时按码元索引理解 0 和 1；若要观察复数星座，选择映射器输出。二值判决输出不生成模拟幅度频谱，不能把索引当作模拟波形的幅度解释。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>为什么输入 −0.0 也输出 1？</strong> 原生判决使用“大于等于零”的规则，正零和负零都满足这个条件。</p><p><strong>能直接判断复数 BPSK 点吗？</strong> 本模块只接收实数。已知判决轴时可先取相应实数分量；需要按完整复数星座点表判决时，使用符号判决器。</p>',27)])])}const b=e(r,[["render",i]]);export{u as __pageData,b as default};
